export const envelope = [48, 36, 32];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const OAK_PLANKS = "minecraft:oak_planks";
  const DARK_PLANKS = "minecraft:dark_oak_planks";
  const SPRUCE_PLANKS = "minecraft:spruce_planks";
  const OAK_LOG_X = "minecraft:oak_log[axis=x]";
  const OAK_LOG_Y = "minecraft:oak_log[axis=y]";
  const OAK_LOG_Z = "minecraft:oak_log[axis=z]";
  const DARK_LOG_X = "minecraft:dark_oak_log[axis=x]";
  const DARK_LOG_Y = "minecraft:dark_oak_log[axis=y]";
  const DARK_LOG_Z = "minecraft:dark_oak_log[axis=z]";
  const ROPE_X = "minecraft:dark_oak_planks";
  const ROPE_Y = "minecraft:dark_oak_planks";
  const IRON = "minecraft:iron_block";
  const COAL = "minecraft:coal_block";
  const GOLD = "minecraft:gold_block";

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function inBelly(x, y, z) {
    return (
      x >= 13 && x <= 29 &&
      y >= 11 && y <= 19 &&
      z >= 10 && z <= 20
    );
  }

  function inDoorGap(x, y, z) {
    return (
      x >= 22 && x <= 27 &&
      y >= 11 && y <= 20 &&
      z >= 5 && z <= 10
    );
  }

  function solidPut(x, y, z, block) {
    if (!inBelly(x, y, z) && !inDoorGap(x, y, z)) {
      put(x, y, z, block);
    }
  }

  function fillBox(x0, y0, z0, x1, y1, z1, block) {
    for (let x = x0; x <= x1; x += 1) {
      for (let y = y0; y <= y1; y += 1) {
        for (let z = z0; z <= z1; z += 1) {
          solidPut(x, y, z, block);
        }
      }
    }
  }

  function fillEllipsoid(cx, cy, cz, rx, ry, rz, block) {
    for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x += 1) {
      for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y += 1) {
        for (let z = Math.floor(cz - rz); z <= Math.ceil(cz + rz); z += 1) {
          const dx = (x - cx) / rx;
          const dy = (y - cy) / ry;
          const dz = (z - cz) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0001) {
            solidPut(x, y, z, block);
          }
        }
      }
    }
  }

  function bodyVoxel(x, y, z) {
    const dx = (x - 21) / 16;
    const dy = (y - 16) / 9;
    const dz = (z - 15) / 10;
    return (
      dx * dx + dy * dy + dz * dz <= 1.0001 &&
      !inBelly(x, y, z) &&
      !inDoorGap(x, y, z)
    );
  }

  for (let x = 4; x <= 38; x += 1) {
    for (let y = 6; y <= 26; y += 1) {
      for (let z = 4; z <= 26; z += 1) {
        const dx = (x - 21) / 16;
        const dy = (y - 16) / 9;
        const dz = (z - 15) / 10;
        if (dx * dx + dy * dy + dz * dz <= 1.0001) {
          const wood = ((x * 7 + y * 3 + z * 5) % 23 === 0)
            ? DARK_PLANKS
            : OAK_PLANKS;
          solidPut(x, y, z, wood);
        }
      }
    }
  }

  for (let x = 12; x <= 30; x += 1) {
    for (let z = 10; z <= 20; z += 1) {
      put(x, 10, z, OAK_PLANKS);
    }
  }

  for (let x = 12; x <= 30; x += 1) {
    put(x, 10, 10, DARK_LOG_X);
    put(x, 10, 20, DARK_LOG_X);
  }

  for (let z = 11; z <= 19; z += 1) {
    put(12, 10, z, DARK_LOG_Z);
    put(30, 10, z, DARK_LOG_Z);
  }

  for (let x = 7; x <= 35; x += 1) {
    if (bodyVoxel(x, 16, 6)) {
      put(x, 16, 6, OAK_LOG_X);
    }
    if (bodyVoxel(x, 16, 24)) {
      put(x, 16, 24, OAK_LOG_X);
    }
    if (bodyVoxel(x, 9, 15)) {
      put(x, 9, 15, OAK_LOG_X);
    }
    if (bodyVoxel(x, 22, 15)) {
      put(x, 22, 15, OAK_LOG_X);
    }
  }

  for (let z = 5; z <= 25; z += 1) {
    if (bodyVoxel(12, 16, z)) {
      put(12, 16, z, OAK_LOG_Z);
    }
    if (bodyVoxel(30, 16, z)) {
      put(30, 16, z, OAK_LOG_Z);
    }
  }

  function terrainY(x, z) {
    let g = Math.floor(api.heightAt(x, z));
    if (g < 0) {
      g = 0;
    }
    if (g > 13) {
      g = 13;
    }
    return g;
  }

  function buildLeg(x0, x1, z0, z1) {
    for (let x = x0; x <= x1; x += 1) {
      for (let z = z0; z <= z1; z += 1) {
        const base = terrainY(x, z);
        put(x, base, z, DARK_PLANKS);
        for (let y = base + 1; y <= 13; y += 1) {
          put(x, y, z, OAK_LOG_Y);
        }
      }
    }
  }

  buildLeg(10, 13, 6, 9);
  buildLeg(10, 13, 21, 24);
  buildLeg(29, 32, 6, 9);
  buildLeg(29, 32, 21, 24);

  fillBox(5, 16, 13, 8, 19, 17, OAK_LOG_X);
  fillBox(4, 18, 13, 6, 20, 17, OAK_LOG_X);
  fillBox(2, 20, 11, 4, 22, 15, DARK_LOG_X);
  fillBox(0, 22, 10, 2, 24, 14, OAK_LOG_X);
  fillBox(0, 23, 10, 1, 25, 14, DARK_PLANKS);

  fillEllipsoid(33, 21, 15, 7, 8, 7, OAK_PLANKS);
  fillEllipsoid(36, 26, 15, 6, 7, 6, OAK_PLANKS);
  fillEllipsoid(40, 29, 15, 6, 5, 6, OAK_PLANKS);
  fillEllipsoid(43, 27, 15, 4, 3, 4, DARK_PLANKS);
  fillBox(45, 25, 12, 47, 29, 18, DARK_PLANKS);

  fillBox(37, 31, 11, 39, 35, 14, OAK_PLANKS);
  fillBox(40, 31, 16, 42, 35, 19, OAK_PLANKS);
  fillBox(37, 35, 11, 39, 35, 14, DARK_PLANKS);
  fillBox(40, 35, 16, 42, 35, 19, DARK_PLANKS);

  for (let x = 38; x <= 42; x += 1) {
    put(x, 30, 9, OAK_LOG_X);
  }

  put(40, 29, 9, COAL);
  put(46, 27, 11, COAL);
  put(46, 27, 19, COAL);

  for (let y = 19; y <= 31; y += 1) {
    const x0 = 29 + Math.floor((y - 19) * 0.55);
    for (let x = x0; x <= x0 + 1; x += 1) {
      solidPut(x, y, 9, DARK_LOG_Y);
      solidPut(x, y, 10, DARK_LOG_Y);
      solidPut(x, y, 20, DARK_LOG_Y);
      solidPut(x, y, 21, DARK_LOG_Y);
    }
  }

  for (let z = 0; z <= 9; z += 1) {
    for (let x = 22; x <= 27; x += 1) {
      const g = terrainY(x, z);
      let top = Math.max(z + 1, g);
      if (top > 10) {
        top = 10;
      }

      for (let y = 0; y <= top; y += 1) {
        let block = OAK_LOG_Y;
        if (y === top) {
          block = ((x + z) % 3 === 0) ? SPRUCE_PLANKS : OAK_PLANKS;
        } else if (y === g) {
          block = DARK_PLANKS;
        }
        put(x, y, z, block);
      }
    }

    for (let side = 0; side < 2; side += 1) {
      const x = side === 0 ? 21 : 28;
      const g = terrainY(x, z);
      let top = Math.max(z + 2, g + 1);
      if (top > 11) {
        top = 11;
      }

      for (let y = 0; y <= top; y += 1) {
        put(x, y, z, y === top ? DARK_LOG_Y : OAK_LOG_Y);
      }
    }
  }

  function shield(cx, cy, sideZ) {
    for (let dx = -3; dx <= 3; dx += 1) {
      for (let dy = -3; dy <= 3; dy += 1) {
        const r2 = dx * dx + dy * dy;
        if (r2 <= 10) {
          let block = OAK_LOG_Z;
          if (r2 <= 4) {
            block = DARK_PLANKS;
          }
          if (r2 === 0) {
            block = GOLD;
          }
          put(cx + dx, cy + dy, sideZ, block);
        }
      }
    }
    put(cx, cy, sideZ + 1, OAK_LOG_Z);
  }

  shield(16, 16, 6);
  shield(31, 16, 8);

  for (let x = 22; x <= 27; x += 1) {
    for (let y = 13; y <= 19; y += 1) {
      put(x, y, 4, SPRUCE_PLANKS);
    }
  }

  for (let y = 13; y <= 19; y += 1) {
    put(22, y, 4, DARK_LOG_Y);
    put(27, y, 4, DARK_LOG_Y);
  }

  for (let z = 4; z <= 9; z += 1) {
    put(22, 20, z, OAK_LOG_Z);
    put(27, 20, z, OAK_LOG_Z);
  }

  for (let x = 22; x <= 27; x += 1) {
    put(x, 20, 4, DARK_LOG_X);
  }

  put(22, 20, 4, GOLD);
  put(27, 20, 4, GOLD);

  for (let y = 9; y <= 12; y += 1) {
    put(22, y, 4, ROPE_Y);
    put(27, y, 4, ROPE_Y);
  }

  for (let y = 10; y <= 21; y += 1) {
    put(21, y, 9, OAK_LOG_Y);
    put(28, y, 9, OAK_LOG_Y);
  }

  for (let x = 21; x <= 28; x += 1) {
    put(x, 10, 9, OAK_LOG_X);
    put(x, 21, 9, OAK_LOG_X);
  }

  for (let sx = 23; sx <= 27; sx += 2) {
    for (let y = 15; y <= 20; y += 1) {
      put(sx, y, 8, OAK_LOG_Y);
    }
    put(sx, 21, 8, IRON);
  }

  for (let y = 24; y <= 28; y += 1) {
    put(43, y, 9, ROPE_Y);
  }

  for (let x = 36; x <= 43; x += 1) {
    put(x, 28, 9, ROPE_X);
  }

  return {
    name: "Trojan Horse of Troy",
    seatY: 0,
    anchors: {
      door: [24, 11, 9]
    },
    interiors: [
      {
        min: [13, 11, 10],
        max: [29, 19, 20],
        kind: "quarters"
      }
    ]
  };
}

