export const envelope = [15, 14, 15];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];
  const lastX = W - 1;
  const lastZ = D - 1;
  const index = api.instance.index;
  const count = api.instance.count;

  const palettes = [
    {
      base: "minecraft:sandstone",
      foundation: "minecraft:stone",
      trim: "minecraft:cut_sandstone",
      mark: "minecraft:chiseled_sandstone",
      roof: "minecraft:smooth_sandstone",
      cracked: "minecraft:cracked_stone_bricks",
      shadow: "minecraft:coal_block",
      wood: "minecraft:dark_oak_log",
      flag: "minecraft:red_wool"
    },
    {
      base: "minecraft:red_sandstone",
      foundation: "minecraft:sandstone",
      trim: "minecraft:cut_red_sandstone",
      mark: "minecraft:chiseled_red_sandstone",
      roof: "minecraft:smooth_red_sandstone",
      cracked: "minecraft:orange_terracotta",
      shadow: "minecraft:polished_blackstone",
      wood: "minecraft:acacia_log",
      flag: "minecraft:blue_wool"
    },
    {
      base: "minecraft:stone_bricks",
      foundation: "minecraft:stone",
      trim: "minecraft:polished_andesite",
      mark: "minecraft:mossy_stone_bricks",
      roof: "minecraft:stone_bricks",
      cracked: "minecraft:cracked_stone_bricks",
      shadow: "minecraft:blackstone",
      wood: "minecraft:spruce_log",
      flag: "minecraft:yellow_wool"
    },
    {
      base: "minecraft:terracotta",
      foundation: "minecraft:brown_terracotta",
      trim: "minecraft:orange_terracotta",
      mark: "minecraft:chiseled_sandstone",
      roof: "minecraft:brown_terracotta",
      cracked: "minecraft:cracked_stone_bricks",
      shadow: "minecraft:coal_block",
      wood: "minecraft:dark_oak_log",
      flag: "minecraft:red_wool"
    }
  ];

  const rFront = api.random();
  const rStyle = api.random();
  const damageSeed = Math.floor(api.random() * 100000);
  const damageLevel = 1 + Math.floor(api.random() * 4);
  const missingRoll = api.random();
  const missingChoice = Math.floor(api.random() * 4);

  const towerTops = [];
  for (let t = 0; t < 4; t += 1) {
    towerTops.push(
      9 + ((Math.floor(api.random() * 3) + index + t) % 3)
    );
  }

  const capSeed = Math.floor(api.random() * 100);
  const crenelSeed = Math.floor(api.random() * 100);
  const canopySeed = Math.floor(api.random() * 100);
  const soldierRoll = api.random();
  const handSeed = Math.floor(api.random() * 100);
  const helmetSeed = Math.floor(api.random() * 100);
  const shieldSeed = Math.floor(api.random() * 100);
  const rearRoll = api.random();
  const peekRoll = api.random();
  const peekSeed = Math.floor(api.random() * 100);
  const flagRowsRoll = api.random();
  const flagSideRoll = api.random();
  const flagColorRoll = api.random();

  const direction =
    (index + count + Math.floor(rFront * 4)) % 4;
  const style =
    (index + count + Math.floor(rStyle * palettes.length)) %
    palettes.length;
  const palette = palettes[style];
  const markerCode = index & 1023;

  const missingTower =
    missingRoll < 0.18 + (index % 5 === 0 ? 0.07 : 0)
      ? missingChoice
      : -1;

  const soldierCount =
    2 + ((index + count + Math.floor(soldierRoll * 2)) % 2);
  const rearCount =
    (index + Math.floor(rearRoll * 3)) % 3;
  const peekCount =
    1 + ((index + Math.floor(peekRoll * 2)) % 2);
  const flagRows = 1 + Math.floor(flagRowsRoll * 3);
  const flagSide = flagSideRoll < 0.5 ? -1 : 1;

  const flagChoices = [
    "minecraft:red_wool",
    "minecraft:blue_wool",
    "minecraft:yellow_wool",
    "minecraft:white_wool"
  ];

  const flagMaterial =
    (index + count + Math.floor(flagColorRoll * 2)) % 2 === 0
      ? palette.flag
      : flagChoices[
          (index + Math.floor(flagColorRoll * flagChoices.length)) %
            flagChoices.length
        ];

  const tunics = [
    "minecraft:blue_wool",
    "minecraft:green_wool",
    "minecraft:gray_wool",
    "minecraft:brown_wool"
  ];

  const skins = [
    "minecraft:terracotta",
    "minecraft:orange_terracotta",
    "minecraft:yellow_terracotta",
    "minecraft:brown_terracotta"
  ];

  const shields = [
    "minecraft:iron_block",
    "minecraft:blue_wool",
    "minecraft:red_wool",
    "minecraft:yellow_concrete",
    "minecraft:green_wool"
  ];

  const helmets = [
    "minecraft:gold_block",
    "minecraft:iron_block",
    "minecraft:yellow_terracotta"
  ];

  const hairBlocks = [
    "minecraft:brown_wool",
    "minecraft:black_wool",
    "minecraft:gray_wool"
  ];

  function toWorld(u, d) {
    if (direction === 0) {
      return [u, d];
    }
    if (direction === 1) {
      return [lastX - d, u];
    }
    if (direction === 2) {
      return [lastX - u, lastZ - d];
    }
    return [d, lastZ - u];
  }

  const occupied = new Set();

  function put(x, y, z, block) {
    if (
      x < 0 || x >= W ||
      y < 0 || y >= H ||
      z < 0 || z >= D
    ) {
      return;
    }

    const key = x + "|" + y + "|" + z;
    if (occupied.has(key)) {
      return;
    }

    occupied.add(key);
    api.set(x, y, z, block);
  }

  function putLocal(u, y, d, block) {
    if (
      u < 0 || u >= W ||
      d < 0 || d >= D ||
      y < 0 || y >= H
    ) {
      return;
    }

    if (
      u >= 4 && u <= 10 &&
      d >= 5 && d <= 9 &&
      y >= 4 && y <= 8
    ) {
      return;
    }

    const point = toWorld(u, d);
    put(point[0], y, point[1], block);
  }

  function isDoor(u, y, d) {
    return (
      (d === 3 || d === 4) &&
      u >= 6 && u <= 8 &&
      y >= 4 && y <= 6
    );
  }

  function wallBlock(u, y, d, face) {
    if (
      face === "front" &&
      d === 3 &&
      u >= 5 && u <= 9 &&
      y >= 7 && y <= 8
    ) {
      const bit = (y - 7) * 5 + (u - 5);
      return (markerCode & (1 << bit)) !== 0
        ? palette.mark
        : palette.trim;
    }

    if (
      face === "back" &&
      d === 10 &&
      (u === 5 || u === 7 || u === 9) &&
      (y === 6 || y === 7)
    ) {
      return palette.shadow;
    }

    const scar =
      (u * 19 + d * 11 + y * 7 + damageSeed + index * 3) % 29;

    if (y >= 5 && scar < damageLevel) {
      return palette.cracked;
    }

    if (
      y === 8 ||
      (u + d + y + style + index) % 6 === 0
    ) {
      return palette.trim;
    }

    return palette.base;
  }

  const terrain = [];
  for (let u = 0; u < W; u += 1) {
    terrain[u] = [];
    for (let d = 0; d < D; d += 1) {
      const point = toWorld(u, d);
      terrain[u][d] = api.heightAt(point[0], point[1]);
    }
  }

  // Buried foundation and a raised stone floor.
  for (let u = 1; u <= W - 2; u += 1) {
    for (let d = 1; d <= D - 2; d += 1) {
      const h = terrain[u][d];
      const lowerBlock =
        h < -0.5 ||
        (u * 3 + d + index + damageSeed) % 7 === 0
          ? palette.foundation
          : palette.base;

      for (let y = 0; y <= 2; y += 1) {
        putLocal(u, y, d, lowerBlock);
      }

      const topBlock =
        (u + d + index + damageSeed) % 4 === 0
          ? palette.trim
          : palette.base;
      putLocal(u, 3, d, topBlock);

      const rise =
        h > 0
          ? Math.min(2, Math.max(0, Math.floor(h + 0.5)))
          : 0;

      const rim =
        u === 1 ||
        u === W - 2 ||
        d === D - 2 ||
        (d === 1 && (u <= 2 || u >= W - 3));

      if (rim) {
        for (let y = 4; y <= 3 + rise; y += 1) {
          putLocal(u, y, d, palette.foundation);
        }
      }
    }
  }

  // Short approach steps at the chosen gate face.
  for (let u = 5; u <= 9; u += 1) {
    const h = terrain[u][0];
    const stepTop = h > 0.5 ? 3 : 2;

    for (let d = 0; d <= 1; d += 1) {
      const limit = d === 0 ? stepTop : 3;
      for (let y = 0; y <= limit; y += 1) {
        putLocal(u, y, d, palette.foundation);
      }
    }
  }

  // Gatehouse walls around the empty inner room.
  for (let y = 4; y <= 8; y += 1) {
    for (let u = 2; u <= 12; u += 1) {
      for (let d = 3; d <= 4; d += 1) {
        if (!isDoor(u, y, d)) {
          putLocal(u, y, d, wallBlock(u, y, d, "front"));
        }
      }
    }

    for (let d = 5; d <= 9; d += 1) {
      putLocal(2, y, d, wallBlock(2, y, d, "side"));
      putLocal(3, y, d, wallBlock(3, y, d, "side"));
      putLocal(11, y, d, wallBlock(11, y, d, "side"));
      putLocal(12, y, d, wallBlock(12, y, d, "side"));
    }

    for (let u = 2; u <= 12; u += 1) {
      putLocal(u, y, 10, wallBlock(u, y, 10, "back"));
      putLocal(u, y, 11, wallBlock(u, y, 11, "back"));
    }
  }

  // Four unequal corner towers.
  const towerBoxes = [
    [1, 4, 2, 5],
    [10, 13, 2, 5],
    [1, 4, 9, 12],
    [10, 13, 9, 12]
  ];

  for (let t = 0; t < towerBoxes.length; t += 1) {
    if (t === missingTower) {
      continue;
    }

    const box = towerBoxes[t];
    const u0 = box[0];
    const u1 = box[1];
    const d0 = box[2];
    const d1 = box[3];
    const top = towerTops[t];

    for (let y = 4; y <= top; y += 1) {
      for (let u = u0; u <= u1; u += 1) {
        for (let d = d0; d <= d1; d += 1) {
          const edge =
            u === u0 || u === u1 ||
            d === d0 || d === d1;

          let block =
            edge || y === top
              ? palette.trim
              : palette.base;

          const towerScar =
            (u * 7 + d * 5 + y * 3 + damageSeed + t * 11) % 31;

          if (
            !edge &&
            y >= 6 &&
            y < top &&
            towerScar < damageLevel
          ) {
            block = palette.cracked;
          }

          putLocal(u, y, d, block);
        }
      }
    }

    if (top + 1 < H) {
      for (let u = u0; u <= u1; u += 1) {
        if ((u + t + index + capSeed) % 2 === 0) {
          putLocal(u, top + 1, d0, palette.mark);
          putLocal(u, top + 1, d1, palette.mark);
        }
      }

      for (let d = d0 + 1; d < d1; d += 1) {
        if ((d + t + index + capSeed) % 2 === 0) {
          putLocal(u0, top + 1, d, palette.mark);
          putLocal(u1, top + 1, d, palette.mark);
        }
      }
    }
  }

  // Solid roof over the quarters.
  for (let u = 2; u <= 12; u += 1) {
    for (let d = 3; d <= 11; d += 1) {
      putLocal(u, 9, d, palette.roof);
    }
  }

  // Parapet and irregular crenellations.
  for (let u = 2; u <= 12; u += 1) {
    putLocal(u, 10, 3, palette.trim);
    putLocal(u, 10, 11, palette.trim);
  }

  for (let d = 4; d <= 10; d += 1) {
    putLocal(2, 10, d, palette.trim);
    putLocal(12, 10, d, palette.trim);
  }

  for (let u = 2; u <= 12; u += 1) {
    if ((u + index + crenelSeed) % 3 !== 1) {
      putLocal(u, 11, 3, palette.mark);
      putLocal(u, 11, 11, palette.mark);
    }
  }

  for (let d = 4; d <= 10; d += 1) {
    if ((d + index + crenelSeed) % 3 !== 1) {
      putLocal(2, 11, d, palette.mark);
      putLocal(12, 11, d, palette.mark);
    }
  }

  // A signal mast and a small cloth pennant.
  for (let y = 10; y <= 13; y += 1) {
    putLocal(7, y, 7, palette.wood);
  }

  for (let y = 11; y < 11 + flagRows && y <= 13; y += 1) {
    putLocal(7 + flagSide, y, 7, flagMaterial);
  }

  // A few helmeted figures peeking over the rear parapet.
  for (let j = 0; j < peekCount; j += 1) {
    const u = 5 + j * 4;
    const d = 10;
    putLocal(u, 10, d, palette.shadow);
    putLocal(
      u,
      11,
      d,
      helmets[(index + j + helmetSeed) % helmets.length]
    );

    if ((index + j + peekSeed) % 2 === 0) {
      putLocal(u, 12, d, palette.mark);
    }
  }

  const spearBlock = "minecraft:oak_fence";

  function makeSoldier(cx, depth, hand, ordinal, rear) {
    const tunic =
      tunics[(ordinal + index + style) % tunics.length];
    const skin =
      skins[(ordinal + index + helmetSeed) % skins.length];
    const shield =
      shields[(ordinal + index + shieldSeed) % shields.length];
    const helmet =
      helmets[(ordinal + index + helmetSeed) % helmets.length];
    const hair =
      hairBlocks[(ordinal + index + helmetSeed) % hairBlocks.length];
    const arm =
      (ordinal + index) % 2 === 0 ? skin : tunic;
    const boots = palette.shadow;
    const helmetOn =
      (helmetSeed + ordinal + index) % 5 !== 0;

    putLocal(cx - 1, 4, depth, boots);
    putLocal(cx, 4, depth, boots);
    putLocal(cx + hand, 5, depth, boots);
    putLocal(cx, 5, depth, tunic);
    putLocal(cx, 6, depth, tunic);
    putLocal(cx + hand, 6, depth, arm);
    putLocal(cx, 7, depth, skin);
    putLocal(cx, 8, depth, helmetOn ? helmet : hair);

    const shieldU = cx + hand;
    const shieldDepth = rear ? depth + 1 : depth - 1;
    const boss =
      (ordinal + index + shieldSeed) % 2 === 0
        ? "minecraft:gold_block"
        : "minecraft:iron_block";

    putLocal(shieldU, 6, shieldDepth, boss);
    putLocal(shieldU, 5, shieldDepth, shield);
    putLocal(shieldU, 7, shieldDepth, shield);
    putLocal(shieldU + hand, 6, shieldDepth, shield);
    putLocal(shieldU + hand, 7, shieldDepth, shield);

    const spearU = cx - hand * 2;
    for (let y = 4; y <= 8; y += 1) {
      putLocal(spearU, y, depth, spearBlock);
    }
    putLocal(spearU, 9, depth, boss);
  }

  // Two guards crouch in the shadow of the gate towers.
  makeSoldier(4, 1, 1, 0, false);
  makeSoldier(10, 1, -1, 1, false);

  // Some variants add another group behind the gatehouse.
  if (soldierCount === 3) {
    const hand = (index + handSeed) % 2 === 0 ? -1 : 1;
    makeSoldier(7, 12, hand, 20, true);
  }

  const rearPositions = [5, 9];
  for (let j = 0; j < rearCount; j += 1) {
    const hand =
      (handSeed + index + j) % 2 === 0 ? -1 : 1;
    makeSoldier(rearPositions[j], 12, hand, 5 + j, true);
  }

  const roomCorners = [
    toWorld(4, 5),
    toWorld(10, 5),
    toWorld(4, 9),
    toWorld(10, 9)
  ];

  let minX = roomCorners[0][0];
  let maxX = roomCorners[0][0];
  let minZ = roomCorners[0][1];
  let maxZ = roomCorners[0][1];

  for (let i = 1; i < roomCorners.length; i += 1) {
    minX = Math.min(minX, roomCorners[i][0]);
    maxX = Math.max(maxX, roomCorners[i][0]);
    minZ = Math.min(minZ, roomCorners[i][1]);
    maxZ = Math.max(maxZ, roomCorners[i][1]);
  }

  const door = toWorld(7, 3);
  const courtyard = toWorld(7, 7);

  return {
    name: "Hidden Greeks behind the Gatehouse",
    seatY: 3,
    anchors: {
      door: [door[0], 4, door[1]],
      courtyard: [courtyard[0], 4, courtyard[1]]
    },
    interiors: [
      {
        min: [minX, 4, minZ],
        max: [maxX, 8, maxZ],
        kind: "quarters"
      }
    ]
  };
}
